  async function renderStates(){loading("Состояния");try{const d=await load("states","admin-states");content.innerHTML=head("Состояния","Аудиторная карта отслеживаемых состояний. Для интенсивности 0–10 уменьшение после сессии считается снижением выраженности; это наблюдаемая связь, а не причинный вывод.")+`<div class="ev-kpis">${kpi(d.items.length,"типов состояний")}${kpi(A(d.items).reduce((a,x)=>a+N(x.count),0),"отметок")}${kpi(A(d.items).reduce((a,x)=>a+N(x.pairs),0),"пар до → после")}${kpi(A(d.items).reduce((a,x)=>a+N(x.trackers),0),"сумма трекеров")}</div><div class="ev-grid3" id="evStatesGrid"></div>`;$("evStatesGrid").innerHTML=A(d.items).map(s=>`<div class="ev-card"><div class="ev-card-title">${esc(s.name)}</div><div class="ev-card-sub">${s.trackers} участ. · ${s.count} отметок · ${s.pairs} измеряемых пар</div><div style="font-size:26px;font-weight:700;margin-top:10px">${N(s.avgIntensity).toFixed(1)}<span style="font-size:10px;color:rgba(255,255,255,.35)"> /10</span></div><div class="ev-pills">${pill(`пик ${s.peak}`)}${s.pairs?pill(`после SETKA ↓ ${N(s.avgSessionDrop).toFixed(2)}`,s.avgSessionDrop>0?"good":""):pill("нет пар")}${pill(`↓ ${s.improved} · = ${s.unchanged} · ↑ ${s.worsened}`)}</div>${s.requests?.length?`<div class="ev-card-sub" style="margin-top:10px">Чаще в сессиях: ${s.requests.slice(0,3).map(([k,n])=>`${INTENT[k]||k} · ${n}`).join(" · ")}</div>`:""}</div>`).join("")||empty("Пока нет состояний");}catch(e){fail(e)}}

  async function renderUx(){loading("UX / Replay");try{const d=await load("ux","admin-ux"),s=d.summary||{},f=s.first||{},r=s.repeat||{};content.innerHTML=head("UX / Replay","Сначала — автоматические признаки понятности интерфейса. Replay нужен для объяснения конкретного случая, а не как единственный способ анализа.")+`<div class="ev-kpis">${kpi(s.all?.visits||0,"визитов с digest")}${kpi(fmtMs(f.avgDurationMs),"средний 1-й визит")}${kpi(f.avgTimeToFirstPatternMs?fmtMs(f.avgTimeToFirstPatternMs):"—","до 1-го паттерна")}${kpi(N(f.avgBacktracks).toFixed(1),"возвратов · 1-й визит")}${kpi(N(f.avgRapidRepeatTaps).toFixed(1),"повторных тапов")}${kpi(N(r.avgBacktracks).toFixed(1),"возвратов · повторные")}</div><div class="ev-grid2"><div class="ev-card"><div class="ev-card-title">Первый опыт</div><div class="ev-card-sub">${f.visits||0} первых визитов · средняя длительность ${fmtMs(f.avgDurationMs)} · ${N(f.avgTaps).toFixed(1)} тапов · ${N(f.avgRevisits).toFixed(1)} повторных экранов.</div></div><div class="ev-card"><div class="ev-card-title">После знакомства</div><div class="ev-card-sub">${r.visits||0} повторных визитов · средняя длительность ${fmtMs(r.avgDurationMs)} · ${N(r.avgTaps).toFixed(1)} тапов · ${N(r.avgRevisits).toFixed(1)} повторных экранов.</div></div></div><div class="ev-section">Replay / Digest</div><div class="ev-table-wrap"><table class="ev-table"><thead><tr><th>Участник</th><th>Старт</th><th>Тип</th><th>Длительность</th><th>События</th><th>Тапы</th><th>Жесты</th><th>RAW</th></tr></thead><tbody>${A(d.replays).map(x=>`<tr class="click" data-device="${esc(x.device_id)}" data-replay="${esc(x.replay_key)}"><td>${esc(x.name)}</td><td>${fmtDate(x.started_at)}</td><td>${x.kind==="free_visit"?"свободный визит":"сессия"}</td><td>${fmtMs(x.duration_ms)}</td><td>${x.event_count||0}</td><td>${N(x.metrics?.taps)}</td><td>${N(x.metrics?.gestures)}</td><td>${x.rawAvailable?pill("Replay доступен","good"):pill("только Digest")}</td></tr>`).join("")}</tbody></table></div>`;content.querySelectorAll("[data-replay]").forEach(x=>x.onclick=()=>openReplay(x.dataset.device,x.dataset.replay));}catch(e){fail(e)}}

  async function openReplay(deviceId,replayKey){const d=await api("admin-replay",{deviceId,replayKey});openModal(d.rawAvailable?"Replay":"Digest визита",d.rawAvailable?"RAW ДО ИСТЕЧЕНИЯ TTL":"ПОСТОЯННАЯ СМЫСЛОВАЯ ПАМЯТЬ");const b=$("evModalBody"),m=d.digest?.metrics||{};if(!d.rawAvailable){b.innerHTML=`<div class="ev-kpis" style="margin-top:14px">${kpi(fmtMs(d.digest?.duration_ms),"длительность")}${kpi(d.digest?.event_count||0,"исходных событий")}${kpi(N(m.taps),"тапов")}${kpi(N(m.gestures),"жестов")}${kpi(N(m.patternOpens),"открытий паттерна")}${kpi(N(m.configChanges),"изменений config")}</div><div class="ev-card"><div class="ev-card-title">Подробный Replay уже удалён</div><div class="ev-card-sub">RAW-координаты закончились по сроку хранения, но аналитический Digest сохранён. Поэтому визит не исчезает из истории и продолжает участвовать в UX-метриках.</div><div class="ev-pills">${pill(`экраны ${A(m.screens).length}`)}${pill(`возвраты ${N(m.backtracks)}`)}${pill(`повторные тапы ${N(m.rapidRepeatTaps)}`)}${pill(`stable config ${A(m.configSummary).length}`)}</div></div>`;return}renderReplayPlayer(b,d.events,d.digest)}

  function renderReplayPlayer(box,events,digest){events=A(events).sort((a,b)=>Date.parse(a.wall_at)-Date.parse(b.wall_at));const t0=events.length?Date.parse(events[0].wall_at):Date.parse(digest?.started_at||Date.now()),duration=Math.max(1000,N(digest?.duration_ms),...events.map(e=>Date.parse(e.wall_at)-t0));box.innerHTML=`<div class="ev-replay-layout" style="margin-top:14px"><div><div class="ev-phone"><canvas id="evReplayCanvas" width="390" height="844"></canvas><div class="ev-phone-overlay"><div id="evReplayCursor" class="ev-cursor"></div><div id="evReplayLabel" class="ev-screen-label"></div></div></div><div class="ev-replay-controls"><button id="evReplayPlay" class="ev-btn primary">▶</button><button class="ev-btn ev-speed active" data-speed="1">×1</button><button class="ev-btn ev-speed" data-speed="2">×2</button><button class="ev-btn ev-speed" data-speed="3">×3</button><button class="ev-btn ev-speed" data-speed="5">×5</button></div><input id="evReplayRange" type="range" min="0" max="${Math.round(duration)}" value="0" style="width:100%;margin-top:8px"><div class="ev-card-sub" id="evReplayTime">0:00 / ${fmtMs(duration)}</div></div><div><div class="ev-card-title">Хронология</div><div id="evReplayEvents" class="ev-event-list">${events.map((e,i)=>`<div class="ev-event" data-ei="${i}">${fmtMs(Date.parse(e.wall_at)-t0)} · ${esc(eventName(e))}</div>`).join("")}</div></div></div>`;const canvas=$("evReplayCanvas"),range=$("evReplayRange"),play=$("evReplayPlay"),cursor=$("evReplayCursor"),label=$("evReplayLabel");let t=0,speed=1,raf=0,last=0,playing=false;function draw(ms){t=Math.max(0,Math.min(duration,ms));range.value=String(Math.round(t));$("evReplayTime").textContent=`${fmtMs(t)} / ${fmtMs(duration)}`;const active=events.filter(e=>Date.parse(e.wall_at)-t0<=t),lastE=active.at(-1),st=lastState(active);drawReplayScene(canvas,st,t,lastE);const p=pointerAt(events,t0,t);if(p){cursor.style.display="block";cursor.style.left=`${p.x*100}%`;cursor.style.top=`${p.y*100}%`}else cursor.style.display="none";label.textContent=lastE?eventName(lastE):"начало";let ai=-1;for(let i=0;i<events.length;i++){if(Date.parse(events[i].wall_at)-t0<=t)ai=i;else break}document.querySelectorAll("#evReplayEvents .ev-event").forEach((x,i)=>x.classList.toggle("active",i===ai));document.querySelector(`#evReplayEvents .ev-event[data-ei="${ai}"]`)?.scrollIntoView?.({block:"nearest"})}function tick(ts){if(!playing)return;if(!last)last=ts;const dt=(ts-last)*speed;last=ts;draw(t+dt);if(t>=duration){playing=false;play.textContent="▶";last=0;return}raf=requestAnimationFrame(tick)}play.onclick=()=>{playing=!playing;play.textContent=playing?"❚❚":"▶";last=0;if(playing)raf=requestAnimationFrame(tick);else cancelAnimationFrame(raf)};range.oninput=()=>{playing=false;play.textContent="▶";draw(Number(range.value))};box.querySelectorAll(".ev-speed").forEach(b=>b.onclick=()=>{speed=N(b.dataset.speed,1);box.querySelectorAll(".ev-speed").forEach(x=>x.classList.toggle("active",x===b))});draw(0)}
  function eventName(e){const p=e.payload||{},m={screen_pointer_down:"касание",screen_pointer_move:"движение пальца",screen_pointer_up:"отпускание",screen_scroll:"скролл",ui_tap:"тап",screen:"экран",view:"режим",library_page:"раздел библиотеки",pattern_open:"открыт паттерн",pattern_state:"изменена конфигурация",gesture_start:"начат жест",gesture_end:"завершён жест",favorite_save:"♥ сохранено",favorite_remove:"♥ снято",note_create:"заметка",game_back:"назад",game_return:"возврат",color:"смена цвета",session_start:"старт сессии",session_end:"конец сессии"};return m[e.type]||e.type+(p.title?` · ${p.title}`:"")}
  function lastState(events){for(let i=events.length-1;i>=0;i--){const p=events[i].payload||{};if(p.state)return p.state}return null}
  function pointerAt(events,t0,t){const pts=events.filter(e=>["screen_pointer_down","screen_pointer_move","screen_pointer_up","screen_pointer_cancel"].includes(e.type));let prev=null,next=null,active=false;for(const e of pts){const et=Date.parse(e.wall_at)-t0;if(et<=t){if(e.type==="screen_pointer_up"||e.type==="screen_pointer_cancel")active=false;else{active=true;prev=e}}else{if(active&&(e.type==="screen_pointer_move"||e.type==="screen_pointer_up")){next=e}break}}if(!active||!prev)return null;const pp=prev.payload||{},x1=N(pp.nx,Number.isFinite(N(pp.x,NaN))?N(pp.x):.5),y1=N(pp.ny,Number.isFinite(N(pp.y,NaN))?N(pp.y):.5);if(!next)return{x:Math.max(0,Math.min(1,x1)),y:Math.max(0,Math.min(1,y1))};const a=Math.max(0,Date.parse(prev.wall_at)-t0),b=Math.max(a+1,Date.parse(next.wall_at)-t0),q=Math.max(0,Math.min(1,(t-a)/(b-a))),np=next.payload||{},x2=N(np.nx,N(np.x,x1)),y2=N(np.ny,N(np.y,y1));return{x:x1+(x2-x1)*q,y:y1+(y2-y1)*q}}
  function drawReplayScene(canvas,state,t,e){const ctx=canvas.getContext("2d"),w=canvas.width,h=canvas.height;ctx.fillStyle="#000";ctx.fillRect(0,0,w,h);if(state?.view==="game"||state?.patternId){drawPattern(canvas,state?.patternId||inferPattern(state),canonicalClient(state?.patternId,state?.configKey,state?.config),N(state?.frame,44)+t/16.6667);return}ctx.strokeStyle="rgba(255,255,255,.18)";ctx.lineWidth=1;for(let i=0;i<12;i++){const x=55+(i%4)*94,y=180+Math.floor(i/4)*100;ctx.beginPath();ctx.arc(x,y,27,0,Math.PI*2);ctx.stroke()}ctx.fillStyle="rgba(255,255,255,.72)";ctx.font="600 20px -apple-system";ctx.textAlign="center";ctx.fillText(e?.payload?.title||"SETKA",w/2,90)}

  async function renderNotes(){loading("Заметки");try{const d=await load("notes","admin-notes",{limit:600});content.innerHTML=head("Заметки","Человеческий смысл поверх чисел. Каждая заметка связана со временем, паттерном и exact-config, поэтому текст можно сопоставлять с поведением, не превращая его в безликий summary.")+`<div class="ev-kpis">${kpi(d.items.length,"заметок")}${kpi(new Set(A(d.items).map(x=>x.deviceId)).size,"участников")}${kpi(new Set(A(d.items).map(x=>x.patternId)).size,"паттернов")}</div><div class="ev-grid3" id="evNotesGrid"></div>`;$("evNotesGrid").innerHTML=A(d.items).map(n=>`<div class="ev-card"><div class="ev-row-title">${esc(n.name)} · ${fmtDate(n.observedAt)}</div><div style="font-size:12px;line-height:1.5;margin-top:9px;white-space:pre-wrap">${esc(n.text)}</div><div class="ev-card-sub" style="margin-top:9px">${esc(PATTERN[n.patternId]||n.patternId)} · ${esc(INTENT[n.requestKey]||n.requestKey||"без запроса")} · ${esc(n.phase||"free")}</div><div class="ev-config-key">${esc(n.configKey)}</div></div>`).join("")||empty("Пока нет заметок");}catch(e){fail(e)}}

  async function renderPhysiology(){loading("Физиология");try{const s=(await load("phys","admin-physiology")).summary;content.innerHTML=head("Физиология","Сначала качество и контекст, потом сырой поток. Simulated-данные считаются отдельно и не смешиваются с реальными физиологическими выводами.")+`<div class="ev-kpis">${kpi(s.realHrSamples,"реальных HR")}${kpi(s.simulatedHrSamples,"simulated HR")}${kpi(s.rrSamples,"RR интервалов")}${kpi(s.sessions,"сессий с HR")}${kpi(s.avgHr==null?"—":Math.round(s.avgHr),"средний реальный BPM")}${kpi(s.minHr==null?"—":`${Math.round(s.minHr)}–${Math.round(s.maxHr)}`,"диапазон BPM")}</div><div class="ev-grid2"><div class="ev-card"><div class="ev-card-title">Что можно анализировать уже сейчас</div><div class="ev-card-sub">HR/RR с timestamp можно связывать с сессией, паттерном и устойчивыми конфигурациями. Реальные и тестовые источники разделены.</div></div><div class="ev-card"><div class="ev-card-title">Следующий уровень</div><div class="ev-card-sub">Для достаточного количества RR будем показывать RMSSD до/после и по стабильным отрезкам конфигураций. Вывод остаётся ассоциативным, не причинным.</div></div></div>`;}catch(e){fail(e)}}

  async function renderFunnel(){loading("Воронка");try{const s=(await load("funnel","admin-funnel")).summary,rate=(v)=>s.participants?Math.round(v/s.participants*100):0;content.innerHTML=head("Воронка","Путь человека от первого знакомства с SETKA до осмысленного использования и возврата. Здесь позже объединятся До ID / Проба и Инвайты.")+`<div class="ev-kpis">${kpi(s.participants,"участников")}${kpi(`${s.openedPattern} · ${rate(s.openedPattern)}%`,"открыли паттерн")}${kpi(`${s.startedSession} · ${rate(s.startedSession)}%`,"начали сессию")}${kpi(`${s.completedOutcome} · ${rate(s.completedOutcome)}%`,"имеют outcome")}${kpi(`${s.savedFavorite} · ${rate(s.savedFavorite)}%`,"сохранили ♥")}${kpi(`${s.returned} · ${rate(s.returned)}%`,"вернулись 2+ дня")}</div><div class="ev-card"><div class="ev-card-title">Основная цепочка</div><div class="ev-row"><div class="ev-row-main"><div class="ev-row-title">Участник</div></div><div>${s.participants}</div></div><div class="ev-row"><div class="ev-row-main"><div class="ev-row-title">Открыл / использовал паттерн</div></div><div>${s.openedPattern}</div></div><div class="ev-row"><div class="ev-row-main"><div class="ev-row-title">Начал формальную сессию</div></div><div>${s.startedSession}</div></div><div class="ev-row"><div class="ev-row-main"><div class="ev-row-title">Есть измеряемая outcome-сессия</div></div><div>${s.completedOutcome}</div></div><div class="ev-row"><div class="ev-row-main"><div class="ev-row-title">Сохранил exact-config</div></div><div>${s.savedFavorite}</div></div><div class="ev-row"><div class="ev-row-main"><div class="ev-row-title">Вернулся в другой день</div></div><div>${s.returned}</div></div></div>`;}catch(e){fail(e)}}

  async function renderSystem(){loading("Данные / система");try{const h=(await load("health","admin-data-health")).health,p=h.policy||{};content.innerHTML=head("Данные / система","Служебная панель здоровья данных. Здесь живёт хранение Replay, качество связей и технические счётчики — отдельно от исследовательской выдачи.","EVOLUTION · DATA HEALTH")+`<div class="ev-kpis">${kpi(h.rawEvents,"RAW событий")}${kpi(h.replays,"Replay digest")}${kpi(h.compacted,"уже сжато")}${kpi(h.pinned,"закреплено")}${kpi(h.facts,"participant facts")}${kpi(h.incompleteCanonicalConfigs,"неполных canonical config")}</div><div class="ev-grid2"><div class="ev-card"><div class="ev-card-title">Хранение RAW Replay</div><div class="ev-card-sub">Подробные движения хранятся временно, смысловые Digest — постоянно.</div><div class="ev-pills" style="margin-top:12px"><button class="ev-btn ${p.retention_days==30?"primary":""}" data-days="30">30 дней</button><button class="ev-btn ${p.retention_days==60?"primary":""}" data-days="60">60 дней</button><button class="ev-btn ${p.retention_days==90?"primary":""}" data-days="90">90 дней</button><button class="ev-btn" id="evCompact">Сжать истёкшее сейчас</button></div><div class="ev-card-sub" style="margin-top:9px">sampling · ${p.sample_hz||8} Hz · последняя очистка ${fmtDate(p.last_compacted_at)}</div></div><div class="ev-card"><div class="ev-card-title">Семантический слой</div><div class="ev-pills">${pill(`${h.snapshots} snapshots`)}${pill(`${h.devices} devices`)}${pill(`${h.communityItems} community`)}${pill(`${h.notes} notes`)}${pill(`${h.physioSamples} physio`)}</div><div class="ev-card-sub" style="margin-top:9px">Evolution использует отдельные participant/pattern/config facts, поэтому глобальные экраны не обязаны скачивать всех пользователей.</div><button class="ev-btn" id="evRebuildFacts" style="margin-top:12px">Пересобрать semantic facts</button></div></div><div class="ev-card" style="margin-top:11px"><div class="ev-card-title">Canonical config</div><div class="ev-card-sub">Правило Evolution: каждая конфигурация должна иметь patternId + configKey + полный canonical config. Старые Dandelion-записи восстанавливаются из configKey даже если исходный object был неполным.</div></div>`;content.querySelectorAll("[data-days]").forEach(b=>b.onclick=async()=>{await api("admin-set-retention",{days:Number(b.dataset.days)});clearCache();renderSystem()});$("evCompact").onclick=async()=>{const x=await api("admin-compact-now");alert(`Удалено RAW событий: ${x.removed||0}`);clearCache();renderSystem()};$("evRebuildFacts").onclick=async()=>{const x=await api("admin-refresh-facts",{force:true});alert(`Пересобрано участников: ${x.rebuilt||0}`);clearCache();renderSystem()};}catch(e){fail(e)}}

  async function openParticipant(deviceId){const d=(await api("admin-participant",{deviceId})).participant;state.participant=d;openModal(d.name,"УЧАСТНИК · ПОЛНАЯ ИСТОРИЯ");const b=$("evModalBody");b.innerHTML=`<div class="ev-participant-tabs"><button class="ev-subtab active" data-pt="summary">Сводка</button><button class="ev-subtab" data-pt="sessions">Сессии</button><button class="ev-subtab" data-pt="patterns">Паттерны</button><button class="ev-subtab" data-pt="states">Состояния</button><button class="ev-subtab" data-pt="ux">UX / Replay</button><button class="ev-subtab" data-pt="notes">Заметки</button><button class="ev-subtab" data-pt="phys">Физиология</button><button class="ev-btn" id="evRename">Переименовать</button></div><div id="evParticipantBody"></div>`;const draw=tab=>{const f=d.fact||{},box=$("evParticipantBody");if(tab==="summary")box.innerHTML=`<div class="ev-kpis">${kpi(fmtBigMs(f.total_pattern_ms),"время паттернов")}${kpi(f.active_days,"активных дней")}${kpi(f.session_count,"сессий")}${kpi(f.free_visit_count,"свободных визитов")}${kpi(f.favorite_count,"♥")}${kpi(f.note_count,"заметок")}</div><div class="ev-grid2"><div class="ev-card"><div class="ev-card-title">Измеряемая часть</div><div class="ev-pills">${pill(`${f.outcome_session_count} outcome`)}${pill(`${f.checkin_count} отметок`)}</div></div><div class="ev-card"><div class="ev-card-title">Исследовательское поведение</div><div class="ev-pills">${pill(`${f.exploration_session_count} exploration`)}${pill(`${f.pattern_opens} открытий`)}${pill(`${f.gestures} жестов`)}</div></div></div>`;
      if(tab==="sessions")box.innerHTML=A(d.sessions).length?`<div class="ev-table-wrap"><table class="ev-table"><thead><tr><th>Старт</th><th>Тип</th><th>Запрос</th><th>До→после</th><th>Время</th></tr></thead><tbody>${A(d.sessions).map(s=>`<tr><td>${fmtDate(s.startedAt)}</td><td>${s.sessionType==="exploration"?"исследование":"outcome"}</td><td>${esc(INTENT[s.requestKey]||s.requestKey)}</td><td>${s.delta==null?"—":`${s.preState}→${s.postState} · Δ ${s.delta>=0?"+":""}${s.delta}`}</td><td>${fmtMs(N(s.measuredActiveMs)+N(s.afterFeedbackActiveMs))}</td></tr>`).join("")}</tbody></table></div>`:empty("Сессий пока нет");
      if(tab==="patterns")box.innerHTML=A(d.patterns).length?`<div class="ev-grid2">${A(d.patterns).map(p=>`<div class="ev-card"><div class="ev-card-title">${esc(PATTERN[p.pattern_id]||p.pattern_id)}</div><div class="ev-pills">${pill(fmtBigMs(p.total_ms),"good")}${pill(`${p.config_count} config`)}${pill(`♥ ${p.favorite_configs}`)}${pill(`${p.session_count} сесс.`)}</div></div>`).join("")}</div>`:empty("Нет данных по паттернам");
      if(tab==="states"){const map=new Map(A(d.states).map(s=>[String(s.id),s]));box.innerHTML=A(d.states).length?`<div class="ev-grid2">${A(d.states).map(s=>{const pts=A(d.checkins).filter(c=>String(c.symptomId)===String(s.id));const vals=pts.map(x=>N(x.intensity));return`<div class="ev-card"><div class="ev-card-title">${esc(s.name)}</div><div class="ev-card-sub">${pts.length} отметок · последняя ${vals.length?vals.at(-1):"—"}/10 · средняя ${vals.length?(vals.reduce((a,b)=>a+b,0)/vals.length).toFixed(1):"—"}</div></div>`}).join("")}</div>`:empty("Состояния не отслеживаются")}
      if(tab==="ux")box.innerHTML=A(d.replays).length?`<div class="ev-table-wrap"><table class="ev-table"><thead><tr><th>Старт</th><th>Тип</th><th>Время</th><th>События</th><th>RAW</th></tr></thead><tbody>${A(d.replays).map(r=>`<tr class="click" data-pr="${esc(r.replay_key)}"><td>${fmtDate(r.started_at)}</td><td>${r.kind}</td><td>${fmtMs(r.duration_ms)}</td><td>${r.event_count}</td><td>${r.compacted_at?"Digest":"Replay"}</td></tr>`).join("")}</tbody></table></div>`:empty("Replay ещё нет");box.querySelectorAll("[data-pr]").forEach(x=>x.onclick=()=>openReplay(d.deviceId,x.dataset.pr));
      if(tab==="notes")box.innerHTML=A(d.notes).length?A(d.notes).slice().reverse().map(n=>`<div class="ev-card" style="margin-bottom:8px"><div class="ev-card-sub">${fmtDate(n.observedAt)} · ${esc(PATTERN[n.patternId]||n.patternId||"")}</div><div style="font-size:12px;line-height:1.5;margin-top:7px">${esc(n.text)}</div></div>`).join(""):empty("Заметок нет");
      if(tab==="phys"){const hr=A(d.physio).filter(x=>x.metric==="heart_rate"),real=hr.filter(x=>x.quality!=="simulated"&&!String(x.sourceType||"").includes("demo"));box.innerHTML=`<div class="ev-kpis">${kpi(hr.length,"HR всего")}${kpi(real.length,"реальных HR")}${kpi(A(d.physio).filter(x=>x.metric==="rr_interval").length,"RR")}</div>`}
    };draw("summary");b.querySelectorAll("[data-pt]").forEach(x=>x.onclick=()=>{b.querySelectorAll("[data-pt]").forEach(y=>y.classList.toggle("active",y===x));draw(x.dataset.pt)});$("evRename").onclick=async()=>{const name=prompt("Имя участника:",d.name);if(name===null||!name.trim())return;await api("admin-rename-participant",{deviceId,label:name.trim()});clearCache();$("evModalTitle").textContent=name.trim();d.name=name.trim();};}

  function openModal(title,eyebrow="SETKA EVOLUTION"){$("evModalTitle").textContent=title;$("evModalEyebrow").textContent=eyebrow;$("evModalBody").innerHTML="";$("evModal").classList.remove("hidden");document.body.style.overflow="hidden"}
  function closeModal(){$("evModal")?.classList.add("hidden");document.body.style.overflow=""}

  function inferPattern(state){const k=String(state?.configKey||"");if(k.startsWith("dandelion|"))return"dandelion";return"tentacle-orbit"}
  function canonicalClient(patternId,key,raw={}){const parts=String(key||"").split("|"),pid=patternId||((parts[0]==="dandelion"||parts[0]==="tentacle-orbit")?parts[0]:null)||(("v1" in (raw||{}))?"dandelion":"tentacle-orbit");if(pid==="dandelion"){const p=parts[0]==="dandelion"?parts.slice(1):[],d=defaultConfig("dandelion"),c={...d,...raw};if(p.length>=9){[c.v1,c.numShapes,c.angleSpeed,c.tSpeed,c.backgroundAlpha,c.lineWeight,c.pointSize,c.zoom,c.colorModeIndex]=[N(p[0],c.v1),Math.round(N(p[1],c.numShapes)),N(p[2],c.angleSpeed),N(p[3],c.tSpeed),Math.round(N(p[4],c.backgroundAlpha)),N(p[5],c.lineWeight),N(p[6],c.pointSize),N(p[7],c.zoom),Math.round(N(p[8],c.colorModeIndex))]}return c}const p=parts[0]==="tentacle-orbit"?parts.slice(1):(parts.length===9?parts:[]),c={...defaultConfig("tentacle-orbit"),...raw};if(p.length>=9){[c.numTentacles,c.tentacleLength,c.baseRadius,c.movementSpeed,c.colorSpeed,c.circleSize,c.lineWeight,c.segmentStep,c.colorModeIndex]=[Math.round(N(p[0],c.numTentacles)),N(p[1],c.tentacleLength),N(p[2],c.baseRadius),N(p[3],c.movementSpeed),N(p[4],c.colorSpeed),N(p[5],c.circleSize),N(p[6],c.lineWeight),Math.round(N(p[7],c.segmentStep)),Math.round(N(p[8],c.colorModeIndex))]}return c}
  function defaultConfig(pid){return pid==="dandelion"?{patternId:"dandelion",v1:.473,numShapes:380,angleSpeed:.01,tSpeed:.005,backgroundAlpha:255,lineWeight:1.2,pointSize:4,zoom:1,colorModeIndex:0}:{patternId:"tentacle-orbit",numTentacles:24,tentacleLength:100,baseRadius:10,movementSpeed:1,colorSpeed:1,circleSize:1,lineWeight:1,segmentStep:2,colorModeIndex:0}}
  function drawPattern(canvas,pid,cfg,frame=44){if(!canvas)return;const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2),w=Math.max(1,Math.round(rect.width||canvas.width||200)),h=Math.max(1,Math.round(rect.height||canvas.height||200));canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);const ctx=canvas.getContext("2d");ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle="#000";ctx.fillRect(0,0,w,h);cfg=canonicalClient(pid,null,cfg);if(pid==="dandelion"){ctx.save();ctx.translate(w/2,h/2);const fit=Math.min(w,h)/470;ctx.scale(fit*cfg.zoom,fit*cfg.zoom);ctx.rotate(Math.sin(frame*cfg.angleSpeed));for(let i=1;i<cfg.numShapes;i++){const z=frame*cfg.tSpeed+i,x=Math.sin(z/10)*100+Math.cos(z/cfg.v1)*100,y=Math.cos(z/10)*100+Math.sin(z/cfg.v1)*100,x2=Math.sin(z/10)*10+Math.cos(z/cfg.v1)*100,y2=Math.cos(z/10)*10+Math.sin(z/cfg.v1)*100;ctx.strokeStyle=dColor(cfg.colorModeIndex,i,x,y,frame*.5,false);ctx.lineWidth=cfg.lineWeight;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x2,y2);ctx.stroke();ctx.fillStyle=dColor(cfg.colorModeIndex,i,x,y,frame*.5,true);ctx.beginPath();ctx.arc(x,y,Math.max(.25,cfg.pointSize/2),0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(x2,y2,Math.max(.25,cfg.pointSize/2),0,Math.PI*2);ctx.fill()}ctx.restore();return}ctx.save();ctx.translate(w/2,h/2);const extent=Math.max(70,cfg.tentacleLength*3.1+cfg.baseRadius+20),fit=(Math.min(w,h)/2-5)/extent;ctx.scale(fit,fit);const shift=frame*cfg.colorSpeed*.5;for(let i=0;i<360;i+=360/cfg.numTentacles){const x0=Math.sin(i*Math.PI/180)*cfg.baseRadius,y0=Math.cos(i*Math.PI/180)*cfg.baseRadius;for(let q=0;q<cfg.tentacleLength;q+=cfg.segmentStep){const a=Math.cos((cfg.tentacleLength-q+frame*cfg.movementSpeed)*Math.PI/180)*q,x=Math.sin((i-a)*Math.PI/180)*q*3,y=Math.cos((i-a)*Math.PI/180)*q*3,d=(cfg.tentacleLength-q)*cfg.circleSize/10;ctx.strokeStyle=tColor(cfg.colorModeIndex,i,q,x,y,shift,frame);ctx.lineWidth=Math.max(.1,cfg.lineWeight/Math.max(.1,fit));ctx.beginPath();ctx.arc(x0+x,y0+y,Math.max(.075,d/2),0,Math.PI*2);ctx.stroke()}}ctx.restore()}
  function mod(n,m){return((n%m)+m)%m}function tColor(mode,i,q,x,y,shift,frame){switch(N(mode)){case 1:return`hsl(${mod(i+q*2+shift,360)} 100% 50%)`;case 2:return`hsl(${mod(frame+q*2,360)} 100% 50%)`;case 3:return"hsl(200 100% 50%)";case 4:return"hsl(330 100% 50%)";case 5:return`hsl(${mod(Math.atan2(y,x)*180/Math.PI+180+shift,360)} 100% 50%)`;case 6:return`hsl(${mod(i+shift,360)} 100% 50%)`;case 7:return`hsl(${mod(q*5+shift,360)} 100% 50%)`;case 8:return`hsl(${mod(x+y+shift,360)} 100% 50%)`;default:return"#fff"}}function dColor(mode,i,x,y,shift,point){const coord=`hsl(${mod((Math.atan2(y,x)+Math.PI)*180/Math.PI*2+shift,360)} 100% 50%)`,idx=`hsl(${mod(i*.8+shift,360)} 100% 50%)`;if(point){if([1,2].includes(N(mode)))return coord;if([5,7].includes(N(mode)))return idx;if([4,8].includes(N(mode)))return"#000";return"#fff"}if([1,3,4].includes(N(mode)))return coord;if([5,6,8].includes(N(mode)))return idx;return"#fff"}

  const dash=$("dashboard");if(dash){const obs=new MutationObserver(()=>{if(!dash.classList.contains("hidden")&&!shell){shell=true;setup()}});obs.observe(dash,{attributes:true,attributeFilter:["class"]});if(!dash.classList.contains("hidden")){shell=true;setup()}}
